@Component("serialNumber-subscriber")
public class SerialNumberSubscriber extends BaseSubscriber {

	public SerialNumberSubscriber() {
	}
	
    public SubscriptionQueryResult<List<SerialNumber>, SerialNumber> serialNumberSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllSerialNumberQuery(), 
                		ResponseTypes.multipleInstancesOf(SerialNumber.class),
                		ResponseTypes.instanceOf(SerialNumber.class));
    }

    public SubscriptionQueryResult<SerialNumber, SerialNumber> serialNumberSubscribe(@DestinationVariable UUID serialNumberId) {
        return queryGateway
                .subscriptionQuery(new FindSerialNumberQuery(new LoadSerialNumberFilter(serialNumberId)), 
                		ResponseTypes.instanceOf(SerialNumber.class),
                		ResponseTypes.instanceOf(SerialNumber.class));
    }





}

